const fs=require('node:fs');
const V=m=>{console.error('DGL_VIOLATION: '+m);process.exit(1)};
const H=m=>{console.error('DGL_HARNESS_ERROR: '+m);process.exit(2)};
try{
 const p='.github/workflows/devgov-v0-attest.yml';
 if(!fs.existsSync(p))H('protected attest workflow file missing');
 const src=fs.readFileSync(p,'utf8');
 if(!/^on:\s*$/m.test(src))H('no on: block found (positive control failed)');
 if(!/^  workflow_call:\s*$/m.test(src))H('workflow_call trigger missing (positive control failed)');
 const lines=src.split('\n');
 const onIdx=lines.findIndex(l=>/^on:\s*$/.test(l));
 if(onIdx===-1)H('on: block index not found');
 let end=lines.length;
 for(let i=onIdx+1;i<lines.length;i++){if(/^\S/.test(lines[i])){end=i;break}}
 const onBlock=lines.slice(onIdx,end).join('\n');
 const hasDispatch=/^  workflow_dispatch:\s*$/m.test(onBlock);
 if(hasDispatch)V('standalone workflow_dispatch trigger coexists with workflow_call in on:');
 console.log('DGL_OK: workflow_call is the sole trigger on devgov-v0-attest.yml');
}catch(e){H('unexpected: '+(e&&e.stack?e.stack:e))}

