const fs=require('node:fs');
const V=m=>{console.error('DGL_VIOLATION: '+m);process.exit(1)};
const H=m=>{console.error('DGL_HARNESS_ERROR: '+m);process.exit(2)};
try{
 const attestPath='.github/workflows/devgov-v0-attest.yml';
 const orchestratePath='.github/workflows/devgov-v0-orchestrate.yml';
 const orchTestPath='scripts/audit/devgovOrchestration.test.ts';
 const trustedTestPath='scripts/audit/devgovTrustedWorkflow.test.ts';
 for(const p of [attestPath,orchestratePath,orchTestPath,trustedTestPath]){if(!fs.existsSync(p))H('expected file missing: '+p)}
 const attestSrc=fs.readFileSync(attestPath,'utf8');
 if(!/^  workflow_call:\s*$/m.test(attestSrc))V('reusable workflow_call trigger lost on attest workflow (positive control failed)');
 const orchSrc=fs.readFileSync(orchestratePath,'utf8');
 const callerCount=(orchSrc.match(/uses:\s*\.\/\.github\/workflows\/devgov-v0-attest\.yml/g)||[]).length;
 if(callerCount<2)V('orchestrator lost its workflow_call reference to the attest workflow (found '+callerCount+')');
 const trustedTestSrc=fs.readFileSync(trustedTestPath,'utf8');
 if(!trustedTestSrc.includes("expect(workflow.on.workflow_dispatch).toBeUndefined();"))V('devgovTrustedWorkflow.test.ts is missing the standalone-dispatch regression assertion');
 if(!trustedTestSrc.includes("expect(Object.keys(workflow.on)).toEqual(['workflow_call']);"))V('devgovTrustedWorkflow.test.ts no longer pins workflow_call as the sole trigger');
 const orchTestSrc=fs.readFileSync(orchTestPath,'utf8');
 if(!orchTestSrc.includes("expect(workflow.on.workflow_dispatch).toBeUndefined();"))V('devgovOrchestration.test.ts still expects a standalone dispatch trigger on the attest workflow');
 console.log('DGL_OK: workflow_call caller intact, no test still expects the removed workflow_dispatch entry point');
}catch(e){H('unexpected: '+(e&&e.stack?e.stack:e))}

