try{
 const win=process.platform==='win32'; const cmd=win?'npx.cmd':'npx';
 const args=['vitest','run','--config','scripts/devgov/vitest.config.mjs','scripts/audit/devgovTrustedWorkflow.test.ts','scripts/audit/devgovOrchestration.test.ts','-t','standalone dispatch entry point|keeps the attestation workflow reusable'];
 const r=cp.spawnSync(cmd,args,{stdio:'inherit',shell:win,timeout:180000});
 if(r.error||r.status===null)H('vitest could not execute: '+(r.error?r.error.message:'signal '+r.signal));
 if(r.status!==0)V('attest-workflow regression tests failed with exit '+r.status);
